import{_ as e,o as n,c as l,ag as r}from"./chunks/framework.D9ghT4bC.js";const h=JSON.parse('{"title":"Unciv 基础术语","description":"","frontmatter":{"title":"Unciv 基础术语"},"headers":[],"relativePath":"zh/Community/Guides/Unciv-basics/index.md","filePath":"zh/Community/Guides/Unciv-basics/index.md"}'),d={name:"zh/Community/Guides/Unciv-basics/index.md"};function a(i,t,c,s,x,y){return n(),l("div",null,[...t[0]||(t[0]=[r('<h1 id="unciv-基础术语" tabindex="-1">Unciv 基础术语 <a class="header-anchor" href="#unciv-基础术语" aria-label="Permalink to &quot;Unciv 基础术语&quot;">​</a></h1><blockquote><p>作者：unciv 贴吧及文明 5 贴吧</p><p>完稿日期：2026年2月12日</p></blockquote><h2 id="术语-简称" tabindex="-1">术语 / 简称 <a class="header-anchor" href="#术语-简称" aria-label="Permalink to &quot;术语 / 简称&quot;">​</a></h2><p>有时玩家们为了追求方便，会简化一些称呼，如将巴比伦弓手简称为巴弓、将大工程师简称为大工，这里不多作赘述，仅介绍一些特殊的简称 / 术语。</p><h3 id="英文简称" tabindex="-1">英文简称 <a class="header-anchor" href="#英文简称" aria-label="Permalink to &quot;英文简称&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:center;">简称</th><th style="text-align:center;">英文全称</th><th style="text-align:center;">含义</th></tr></thead><tbody><tr><td style="text-align:center;">T</td><td style="text-align:center;">Turn</td><td style="text-align:center;">回合</td></tr><tr><td style="text-align:center;">UU</td><td style="text-align:center;">Unique Unit</td><td style="text-align:center;">特有单位</td></tr><tr><td style="text-align:center;">UA</td><td style="text-align:center;">Unique Ability</td><td style="text-align:center;">特有能力</td></tr><tr><td style="text-align:center;">UB</td><td style="text-align:center;">Unique Building</td><td style="text-align:center;">特有建筑</td></tr><tr><td style="text-align:center;">UI</td><td style="text-align:center;">Unique Improvement</td><td style="text-align:center;">特有设施</td></tr><tr><td style="text-align:center;">MOD</td><td style="text-align:center;">Modification</td><td style="text-align:center;">游戏扩展程序，即模组</td></tr><tr><td style="text-align:center;">TJ</td><td style="text-align:center;">空</td><td style="text-align:center;">太监，即还没打完就不玩了</td></tr><tr><td style="text-align:center;">G</td><td style="text-align:center;">Gold</td><td style="text-align:center;">金，即金钱、现金</td></tr><tr><td style="text-align:center;">AI</td><td style="text-align:center;">artificial intelligence</td><td style="text-align:center;">人工智能，即电脑玩家</td></tr><tr><td style="text-align:center;">RA</td><td style="text-align:center;">Research Agreement</td><td style="text-align:center;">科研协议</td></tr><tr><td style="text-align:center;">GPT</td><td style="text-align:center;">Gold Per Turn</td><td style="text-align:center;">回合金，即每回合获得的金币</td></tr><tr><td style="text-align:center;">SL</td><td style="text-align:center;">Save Load (Ciallo~)</td><td style="text-align:center;">即保存，读档</td></tr></tbody></table><h3 id="奇观简称" tabindex="-1">奇观简称 <a class="header-anchor" href="#奇观简称" aria-label="Permalink to &quot;奇观简称&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:center;">简称</th><th style="text-align:center;">对应奇观</th></tr></thead><tbody><tr><td style="text-align:center;">弓庙、粮庙、吃货庙</td><td style="text-align:center;">阿尔忒弥斯神庙</td></tr><tr><td style="text-align:center;">经验门</td><td style="text-align:center;">勃兰登堡门</td></tr><tr><td style="text-align:center;">齐秦</td><td style="text-align:center;">奇琴伊察</td></tr><tr><td style="text-align:center;">面包山</td><td style="text-align:center;">艾尔斯岩石</td></tr><tr><td style="text-align:center;">冰淇淋山</td><td style="text-align:center;">冈仁波齐峰</td></tr><tr><td style="text-align:center;">科研火山</td><td style="text-align:center;">喀拉喀托火山</td></tr><tr><td style="text-align:center;">宗教山</td><td style="text-align:center;">西奈山、艾尔斯岩石、圣足山等提供大量信仰的自然奇观</td></tr></tbody></table><h3 id="单位简称" tabindex="-1">单位简称 <a class="header-anchor" href="#单位简称" aria-label="Permalink to &quot;单位简称&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:center;">简称</th><th style="text-align:center;">对应单位</th></tr></thead><tbody><tr><td style="text-align:center;">猴子、狗</td><td style="text-align:center;">斥候</td></tr><tr><td style="text-align:center;">小矛、叉叉、叉子</td><td style="text-align:center;">矛兵（枪兵）</td></tr><tr><td style="text-align:center;">棒子、鸡腿</td><td style="text-align:center;">勇士</td></tr><tr><td style="text-align:center;">妹子</td><td style="text-align:center;">工人</td></tr><tr><td style="text-align:center;">小弓</td><td style="text-align:center;">弓箭手</td></tr><tr><td style="text-align:center;">车射、车车</td><td style="text-align:center;">战车射手</td></tr><tr><td style="text-align:center;">大仙</td><td style="text-align:center;">大先知（大预言家）</td></tr><tr><td style="text-align:center;">小仙</td><td style="text-align:center;">传教士</td></tr></tbody></table><h3 id="建筑简称" tabindex="-1">建筑简称 <a class="header-anchor" href="#建筑简称" aria-label="Permalink to &quot;建筑简称&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:center;">简称</th><th style="text-align:center;">对应建筑</th></tr></thead><tbody><tr><td style="text-align:center;">小庙</td><td style="text-align:center;">神社</td></tr><tr><td style="text-align:center;">大庙</td><td style="text-align:center;">寺庙</td></tr></tbody></table><h3 id="宗教简称" tabindex="-1">宗教简称 <a class="header-anchor" href="#宗教简称" aria-label="Permalink to &quot;宗教简称&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:center;">简称</th><th style="text-align:center;">对应内容</th></tr></thead><tbody><tr><td style="text-align:center;">沙神</td><td style="text-align:center;">沙漠民俗</td></tr></tbody></table><h3 id="常用术语" tabindex="-1">常用术语 <a class="header-anchor" href="#常用术语" aria-label="Permalink to &quot;常用术语&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:center;">术语</th><th style="text-align:center;">含义</th></tr></thead><tbody><tr><td style="text-align:center;">爆铺</td><td style="text-align:center;">多铺城，靠大量城市发展国力的玩法</td></tr><tr><td style="text-align:center;">精铺</td><td style="text-align:center;">少铺城，专注发展少量优质城市的玩法</td></tr><tr><td style="text-align:center;">魔王流</td><td style="text-align:center;">顶着大量红脸继续推进</td></tr><tr><td style="text-align:center;">蘑菇</td><td style="text-align:center;">指不铺城，光发展的 AI 或玩家，就好像蘑菇一样等人采</td></tr><tr><td style="text-align:center;">种田</td><td style="text-align:center;">专注发展自身国力</td></tr><tr><td style="text-align:center;">骗宣</td><td style="text-align:center;">将手中按回合交付的资源等换 AI 手中的现金后宣战，这样你拿到了现金而 AI 却什么都得不到</td></tr><tr><td style="text-align:center;">买宣</td><td style="text-align:center;">用金钱等交易让 AI 宣战别人</td></tr><tr><td style="text-align:center;">背刺</td><td style="text-align:center;">长期友好或中立后突然敌对或宣战</td></tr><tr><td style="text-align:center;">开门</td><td style="text-align:center;">启用一个政策树，有对应效果</td></tr><tr><td style="text-align:center;">关门</td><td style="text-align:center;">点亮完一个政策树所有的政策，有对应效果</td></tr><tr><td style="text-align:center;">刮刮乐</td><td style="text-align:center;">通过工人不断修复地块设施进行反复劫掠</td></tr><tr><td style="text-align:center;">勾引大法</td><td style="text-align:center;">主动用工人吸引敌军进入某地块后围殴</td></tr><tr><td style="text-align:center;">自主左二、传统右二等称呼</td><td style="text-align:center;">对 xx 政策树左边 / 中间 / 右边第 x 个政策的简称</td></tr><tr><td style="text-align:center;">锤子</td><td style="text-align:center;">产能</td></tr><tr><td style="text-align:center;">瓶子</td><td style="text-align:center;">科研点数</td></tr><tr><td style="text-align:center;">鸽子</td><td style="text-align:center;">信仰点数</td></tr><tr><td style="text-align:center;">坐城</td><td style="text-align:center;">建立城市</td></tr></tbody></table>',16)])])}const o=e(d,[["render",a]]);export{h as __pageData,o as default};
